import { jsPDF } from 'jspdf';
import QRCode from 'qrcode';
import { label, normalize } from '../src/catalog.js';

const LOGO = 'data:image/jpeg;base64,';
const C = { slate: '#96abb0', dark: '#283d40', paper: '#f5f7f6', line: '#dce4e3', muted: '#53686b', white: '#ffffff', pale: '#e8eeed' };
const W = 210, H = 297, M = 17, CW = W - M * 2;
const CONTACT = { phone: '01425 274000', phoneLink: 'tel:01425274000', email: 'info@coastalgardenbuildings.co.uk', web: 'https://www.coastalgardenbuildings.co.uk/' };
const currency = value => Number.isFinite(Number(value)) && value !== null && value !== '' ? `£${Math.round(Number(value)).toLocaleString('en-GB')}` : null;
const clean = (value, max = 1000) => String(value ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const safeLink = value => { try { const u = new URL(value); return ['https:', 'http:'].includes(u.protocol) ? u.href : CONTACT.web; } catch { return CONTACT.web; } };
const range = (low, high) => { const l = currency(low), h = currency(high); return l && h ? l === h ? l : `${l} - ${h}` : 'Dealer quotation required'; };
const systemDetails = { log: 'Interlocking timber construction. The final wall thickness and full specification are agreed with Coastal.', prima: 'Post-and-panel construction with modular dimensions. Coastal confirms the panels, openings and final specification.', pro: 'Post-and-beam construction. The selected layout and final build specification are agreed with Coastal.' };

/** Creates a private, personalised concept guide from one accepted design/quote snapshot. */
export async function generateProposal({ design, quote = {}, lead = {}, hero, detail: secondView, plan, link } = {}) {
  const d = normalize(design || {}), q = quote || {}, person = clean(lead.name, 160) || 'Your Coastal design';
  const ref = clean(q.reference, 80) || 'COASTAL-DESIGN';
  const created = new Date(q.createdAt || Date.now());
  const date = Number.isNaN(created.getTime()) ? new Date().toLocaleDateString('en-GB') : created.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
  const resume = safeLink(link), doc = new jsPDF({ unit: 'mm', format: 'a4', compress: true });
  const title = `${d.width.toFixed(1)}m x ${d.depth.toFixed(1)}m ${label('system', d.system).toLowerCase()}`;
  const area = (d.width * d.depth).toFixed(1), fullPrice = range(q.low, q.high);
  let page = 0;
  const pageTotal = imageData(secondView) ? 7 : 6;
  doc.setProperties({ title: `${ref} | Your Coastal garden room`, subject: 'Personalised concept design and indicative budget guide', author: 'Coastal Garden Buildings', keywords: 'Coastal, garden room, design, indicative budget, concept' });

  function font(size = 10, style = 'normal', color = C.dark) { doc.setFont('helvetica', style); doc.setFontSize(size); doc.setTextColor(color); }
  function fill(color) { doc.setFillColor(color); }
  function box(x, y, w, h, color = C.paper, radius = 2) { fill(color); doc.roundedRect(x, y, w, h, radius, radius, 'F'); }
  function rule(y, color = C.line) { doc.setDrawColor(color); doc.setLineWidth(.3); doc.line(M, y, W - M, y); }
  function text(value, x, y, width = CW, size = 10, color = C.dark, style = 'normal', options = {}) {
    font(size, style, color); const lines = doc.splitTextToSize(clean(value), width); doc.text(lines, x, y, { lineHeightFactor: 1.42, ...options }); return y + lines.length * size * .3528 * 1.42;
  }
  function fit(value, x, y, width, size = 10, style = 'normal', color = C.dark, min = 7.5) {
    const s = clean(value); let actual = size; font(actual, style, color);
    while (doc.getTextWidth(s) > width && actual > min) { actual -= .25; font(actual, style, color); }
    if (doc.getTextWidth(s) <= width) { doc.text(s, x, y); return y + actual * .5; }
    const lines = doc.splitTextToSize(s, width).slice(0, 2); doc.text(lines, x, y, { lineHeightFactor: 1.25 }); return y + lines.length * actual * .45;
  }
  function tag(value, x, y, width) { box(x, y, width, 10, C.pale, 1); fit(value, x + 4, y + 6.4, width - 8, 8.2, 'bold'); }
  function button(value, x, y, width, url, dark = true) {
    box(x, y, width, 13, dark ? C.dark : C.pale, 1.4); fit(value, x + 5, y + 8.1, width - 10, 9.2, 'bold', dark ? C.white : C.dark);
    doc.link(x, y, width, 13, { url });
  }
  function imageData(value) { const src = typeof value === 'string' ? value : value?.dataUrl || value?.dataURL; return /^data:image\/(?:png|jpe?g|webp);base64,/i.test(src || '') && src.length < 6500000 ? src : null; }
  function graphic(value, x, y, width, height, cover = false) {
    const src = imageData(value); if (!src) return false;
    try { const img = doc.getImageProperties(src), scale = cover ? Math.max(width / img.width, height / img.height) : Math.min(width / img.width, height / img.height); const iw = img.width * scale, ih = img.height * scale; doc.addImage(src, img.fileType, x + (width - iw) / 2, y + (height - ih) / 2, iw, ih, undefined, 'FAST'); return true; } catch { return false; }
  }
  function qr(value, x, y, size) {
    try {
      const matrix = QRCode.create(value, { errorCorrectionLevel: 'M' }).modules;
      const unit = size / (matrix.size + 8);
      fill(C.white); doc.rect(x, y, size, size, 'F'); fill(C.dark);
      for (let row = 0; row < matrix.size; row++) for (let col = 0; col < matrix.size; col++) if (matrix.data[row * matrix.size + col]) doc.rect(x + (col + 4) * unit, y + (row + 4) * unit, unit + .005, unit + .005, 'F');
      doc.link(x, y, size, size, { url: value }); return true;
    } catch { return false; }
  }
  function footer() {
    rule(280); fit(`${ref} | Concept design`, M, 286, 84, 7.6, 'normal', C.muted);
    font(7.6, 'normal', C.muted); doc.text(`Coastal Garden Buildings | ${CONTACT.phone}`, 112, 286);
    doc.text(`${page} / ${pageTotal}`, W - M, 292, { align: 'right' });
  }
  function newPage(name, subtitle) {
    if (page) doc.addPage(); page += 1;
    fill(C.white); doc.rect(0, 0, W, H, 'F'); fill(C.slate); doc.rect(0, 0, W, 4, 'F');
    doc.addImage(LOGO, 'JPEG', M, 10, 31, 21.12);
    font(8.2, 'bold', C.dark); doc.text('YOUR PERSONAL DESIGN GUIDE', W - M, 15, { align: 'right' });
    font(7.8, 'normal', C.muted); doc.text(date, W - M, 21, { align: 'right' });
    font(7.5, 'normal', C.muted); doc.text(ref, W - M, 27, { align: 'right' });
    rule(36); text(name, M, 51, CW, 26, C.dark, 'bold');
    if (subtitle) text(subtitle, M, 61, CW, 10, C.muted);
    footer();
  }
  function smallHeading(value, x, y, width = CW, color = C.muted) { text(value.toUpperCase(), x, y, width, 8.8, color, 'bold'); }
  function boundedText(value, x, y, width, maxLines, size = 8.3, color = C.muted) {
    let actual = size, lines; font(actual, 'normal', color); lines = doc.splitTextToSize(clean(value), width);
    while (lines.length > maxLines && actual > 6.5) { actual -= .25; font(actual, 'normal', color); lines = doc.splitTextToSize(clean(value), width); }
    if (lines.length > maxLines) { lines = lines.slice(0, maxLines); lines[maxLines - 1] = lines[maxLines - 1].replace(/\s+\S*$/, '') + '...'; }
    doc.text(lines, x, y, { lineHeightFactor: 1.35 });
  }
  function bullet(value, x, y, width = CW, size = 9.7) {
    fill(C.slate); doc.circle(x + 1, y - 1.3, .9, 'F'); return text(value, x + 5, y, width - 5, size) + 3.2;
  }
  function detail(labelText, value, y, { height = 18 } = {}) {
    rule(y - 4); text(labelText, M, y + 1, 42, 9, C.muted, 'bold'); text(value, M + 46, y + 1, CW - 46, 10); return y + height;
  }
  function drawPlan(x, y, width, height) {
    box(x, y, width, height, C.paper, 2);
    const sideCanopy = d.canopy || 0, scale = Math.min((width - 46) / (d.width + sideCanopy), (height - 44) / d.depth);
    const rw = d.width * scale, rd = d.depth * scale, canopyW = sideCanopy * scale, left = x + (width - rw - canopyW) / 2, top = y + 15;
    doc.setDrawColor(C.dark); doc.setLineWidth(1.65); doc.setFillColor(C.white); doc.rect(left, top, rw, rd, 'FD');
    if (sideCanopy) { doc.setDrawColor(C.slate); doc.setLineWidth(.5); doc.setLineDashPattern([1.3, 1], 0); doc.rect(left + rw, top, canopyW, rd); doc.setLineDashPattern([], 0); font(7.2, 'normal', C.muted); doc.text(['1.5m', 'side canopy', 'concept'], left + rw + canopyW / 2, top + rd / 2 - 5, { align: 'center', lineHeightFactor: 1.35 }); }
    const doorW = Math.min(d.width - .65, ({ french: 1.7, sliding: 2.45, bifold: 2.9 })[d.glazing]) * scale, doorX = left + (rw - doorW) / 2;
    doc.setDrawColor(C.white); doc.setLineWidth(2.4); doc.line(doorX, top + rd, doorX + doorW, top + rd);
    doc.setDrawColor(C.slate); doc.setLineWidth(.85); doc.line(doorX, top + rd, doorX + doorW, top + rd);
    if (d.window !== 'none') for (const side of d.window === 'both' ? ['left', 'right'] : [d.window]) {
      const wx = side === 'left' ? left : left + rw, windowLength = Math.min(d.depth - .7, 1.5) * scale, wy = top + (rd - windowLength) / 2;
      doc.setDrawColor(C.white); doc.setLineWidth(2.4); doc.line(wx, wy, wx, wy + windowLength); doc.setDrawColor(C.slate); doc.setLineWidth(.85); doc.line(wx, wy, wx, wy + windowLength);
    }
    doc.setDrawColor(C.muted); doc.setLineWidth(.2);
    doc.line(left, top - 7, left + rw, top - 7); doc.line(left, top - 9, left, top - 5); doc.line(left + rw, top - 9, left + rw, top - 5);
    font(9.2, 'bold'); doc.text(`${d.width.toFixed(1)}m`, left + rw / 2, top - 9, { align: 'center' });
    doc.line(left + rw + canopyW + 8, top, left + rw + canopyW + 8, top + rd); doc.line(left + rw + canopyW + 6, top, left + rw + canopyW + 10, top); doc.line(left + rw + canopyW + 6, top + rd, left + rw + canopyW + 10, top + rd);
    font(8.5, 'bold'); doc.text(`${d.depth.toFixed(1)}m`, left + rw + canopyW + 11, top + rd / 2 + 1);
    font(16, 'bold'); doc.text(`${area} m²`, left + rw / 2, top + rd / 2, { align: 'center' });
    font(7.8, 'normal', C.muted); doc.text('external room footprint', left + rw / 2, top + rd / 2 + 6, { align: 'center' });
    font(7.8, 'bold', C.muted); doc.text('FRONT / GARDEN ENTRANCE', left + rw / 2, Math.min(y + height - 6, top + rd + 9), { align: 'center' });
  }

  // 1: personal cover, immediate value and a faithful design visual.
  newPage('Room for the life you love.', 'Your ideas, brought together in one personal design and budget guide.');
  smallHeading('Prepared for', M, 76); fit(person, M, 84, CW, 15, 'bold', C.dark, 11);
  tag(`${d.width.toFixed(1)}m x ${d.depth.toFixed(1)}m`, M, 94, 54); tag(`${area}m² footprint`, M + 61, 94, 54); tag(label('roof', d.roof) + ' roof', M + 122, 94, 54);
  box(M, 113, CW, 98, C.paper, 2);
  if (!graphic(hero, M + 2, 115, CW - 4, 93)) drawPlan(M, 113, CW, 98);
  text('Concept preview. Colours, openings, furniture and the garden setting are illustrative. Final details are agreed with Coastal.', M, 217, CW, 7.8, C.muted);
  smallHeading('Indicative supply budget', M, 233); fit(fullPrice, M, 245, 131, 23, 'bold');
  text('Including VAT. Assembly, delivery, base, site works and mains connections need a separate dealer quotation.', M, 253, 131, 8.8, C.muted);
  if (qr(resume, W - M - 30, 229, 30)) { font(6.8, 'normal', C.muted); doc.text('Scan to revisit your design', W - M - 15, 261.5, { align: 'center' }); }
  button('Reopen and refine my design', M, 263, 92, resume); button('Talk to Coastal', M + 100, 263, 76, CONTACT.phoneLink, false);

  if (imageData(secondView)) {
    newPage('Another view of your room.', 'A complementary perspective on your chosen design.');
    box(M, 78, CW, 106, C.paper, 2);
    if (!graphic(secondView, M + 1, 79, CW - 2, 104)) drawPlan(M, 78, CW, 106);
    text('The same building, viewed from the other side. The setting, furnishings and finishes are illustrative; the final specification is agreed with Coastal.', M, 192, CW, 8.3, C.muted);
    const selections = [['Your roofline', label('roof', d.roof) + ' roof'], ['Timber finish', label('timber', d.timber)], ['Your entrance', label('glazing', d.glazing)]];
    selections.forEach(([name, value], index) => {
      const x = M + index * 61;
      box(x, 211, 54, 35, C.pale, 1.5);
      smallHeading(name, x + 4, 220, 46);
      fit(value, x + 4, 235, 46, 11.5, 'bold');
    });
    text('Keep exploring: the following plan and specification set out the external dimensions, opening preferences and selected options.', M, 259, CW, 9, C.muted);
  }

  // An accessible vector plan and opening preferences, without invented build dimensions.
  newPage('A space that fits your life.', 'Review the shape, light and access before discussing the exact fit with Coastal.');
  if (imageData(plan)) { box(M, 78, CW, 117, C.paper); if (!graphic(plan, M + 2, 80, CW - 4, 113)) drawPlan(M, 78, CW, 117); }
  else drawPlan(M, 78, CW, 117);
  text('External room dimensions. The canopy is additional when selected. Internal usable space will be smaller. This plan is indicative and not to scale or for construction.', M, 202, CW, 8.5, C.muted);
  let y = 223;
  y = detail('Your entrance', `${label('glazing', d.glazing)}; final opening size, position and handing to be confirmed.`, y, { height: 21 });
  y = detail('Side windows', `${label('window', d.window)}. Left and right are viewed from the garden, facing the entrance.`, y, { height: 22 });
  text('Bring your furniture sizes and preferred garden views to the design conversation. Coastal can help balance light, privacy and useful wall space.', M, Math.min(y, 267), CW, 8.3, C.muted);

  // 3: every normalized design choice, plus truthful fulfilment boundaries.
  newPage('Every choice, in one place.', 'Your selected concept specification - ready to refine with a Coastal specialist.');
  y = 79;
  y = detail('How you will use it', label('use', d.use), y);
  y = detail('Building system', label('system', d.system), y);
  y = detail('External size', `${d.width.toFixed(1)}m wide x ${d.depth.toFixed(1)}m deep; ${area}m² room footprint`, y);
  y = detail('Roof', `${label('roof', d.roof)} roof; final height, drainage and covering to be confirmed`, y, { height: 22 });
  y = detail('Exterior preference', `${label('timber', d.timber)}; exact finish, treatment and colour are agreed from samples`, y, { height: 22 });
  y = detail('Doors & windows', `${label('glazing', d.glazing)}; ${label('window', d.window).toLowerCase()}`, y);
  y = detail('Side canopy', d.canopy ? '1.5m side canopy requested; final structure and base scope to be confirmed' : 'No side canopy selected', y, { height: 21 });
  y = detail('Insulation', d.insulated ? 'Insulation requested. Coastal confirms the full system, scope and cost.' : 'No insulation requested. Ask Coastal about options for your intended use.', y, { height: 22 });
  box(M, 247, CW, 27, C.pale); text(systemDetails[d.system], M + 5, 254, CW - 10, 9.2);

  // 4: range estimates remain explicitly different from an exact manufacturer quotation.
  newPage('Your investment, made clear.', 'A realistic starting conversation. Your final specification and price are confirmed by Coastal.');
  box(M, 77, CW, 35, C.dark); smallHeading('Indicative supply budget, including VAT', M + 6, 86, CW - 12, C.pale); fit(fullPrice, M + 6, 103, CW - 12, 25, 'bold', C.white);
  y = 124; smallHeading('Budget allowances', M, y); y += 11;
  const options = Array.isArray(q.options) ? q.options.filter(item => item && typeof item === 'object').slice(0, 6) : [];
  const budgetRows = [{ label: 'Building supply allowance', low: q.baseLow, high: q.baseHigh }, ...options];
  for (const item of budgetRows) { rule(y - 4); boundedText(clean(item.label, 180), M, y + 1, 111, 2, 9.2, C.dark); fit(range(item.low, item.high), 135, y + 1, 58, 9.8, 'bold', C.dark); y += 11.5; }
  const scopeY = Math.max(183, y + 2);
  smallHeading('Quoted separately for your garden', M, scopeY);
  boundedText('Assembly and installation; delivery; a suitable base and site preparation; mains electricity and any plumbing; final glazing, treatments and requested upgrades outside the confirmed supply scope.', M, scopeY + 8, CW, 3, 9.1);
  const basisY = Math.max(scopeY + 28, 239);
  boundedText(clean(q.basis, 850) || 'Unpromoted Lugarde 44mm log-cabin shell references: 3x3m £3,730; 4x3m £4,495; 5x3m £5,440, checked 11 October 2026. Other sizes and systems use an indicative model. Delivery, assembly, bases and connections are excluded. No promotional discount assumed.', M, basisY, CW, 3, 8.1);
  boundedText('This guide is an indicative budget range, not a fixed-price offer. VAT is included in the displayed ranges. Coastal confirms availability, buildability, exact scope, current prices and terms before you order.', M, 265, CW, 2, 8.3);

  // 5: useful, use-specific preparation without unsupported planning promises.
  newPage('Ready for your garden.', 'A few practical details will help Coastal turn your starting design into the right proposal.');
  const useAdvice = { office: 'Measure desks, chairs and storage. Leave room to pull a chair back and plan power, internet and a comfortable working temperature.', gym: 'Check equipment sizes, headroom and clear movement space. Discuss ventilation, flooring loads and comfort with Coastal.', studio: 'Measure your worktable, tools and storage. Consider daylight, electrical needs and clear routes around your workspace.', retreat: 'Measure sofas, chairs and storage. Think about views, privacy and how you want to use the room throughout the year.' };
  box(M, 79, CW, 34, C.pale); text(useAdvice[d.use], M + 6, 87, CW - 12, 10);
  const checklists = [
    ['Space & boundaries', 'Measure the available garden space, distance to boundaries and any slopes. The dimensions in this guide are external.'],
    ['Access & delivery', 'Note gate widths, steps, narrow passages and the route from the road to the garden. Coastal confirms the delivery and installation approach.'],
    ['A suitable base', 'Discuss a level, load-bearing base and any site preparation. Existing bases and ground conditions need review.'],
    ['Power & year-round use', 'Tell Coastal about electricity, internet, heating or cooling needs. Insulation and mains connections are confirmed in the final scope.'],
    ['Planning & permissions', 'Requirements depend on your site, location, size, height and intended use. Check the appropriate permissions and approvals before ordering.'],
  ];
  y = 129;
  for (let i = 0; i < checklists.length; i++) { const [name, copy] = checklists[i]; tag(String(i + 1).padStart(2, '0'), M, y - 4, 13); text(name, M + 19, y + 1, CW - 19, 11, C.dark, 'bold'); text(copy, M + 19, y + 8, CW - 19, 9.4); y += 29; }
  text('This concept is a garden building design. Sleeping accommodation or other specialist uses need a separate suitability and permissions review.', M, 272, CW, 7.9, C.muted);

  // 6: one clear, real next step; no unconfigured email or appointment promises.
  newPage('Let’s make it Coastal.', 'Bring your ideas. We will help you work through the practical details.');
  box(M, 78, CW, 49, C.dark); text('Your next step: a design conversation.', M + 7, 91, CW - 14, 17, C.white, 'bold'); text('Talk through the room, your garden, the supply and assembly options, and the route to a written dealer quotation.', M + 7, 105, CW - 14, 10, C.white);
  y = 143;
  for (const [n, name, copy] of [['01', 'Explore your design', 'Review the dimensions, construction system, glazing, finish and how you plan to use the space.'], ['02', 'Confirm the details', 'Agree site requirements, delivery, base, assembly, selected upgrades and the final specification with Coastal.'], ['03', 'Get your written quotation', 'Coastal confirms current availability, exact prices, payment terms and the delivery or installation arrangements.']]) { tag(n, M, y - 4, 13); text(name, M + 19, y + 1, CW - 19, 11, C.dark, 'bold'); text(copy, M + 19, y + 8, CW - 19, 9.4); y += 29; }
  rule(230); smallHeading('See the buildings. Talk through your ideas.', M, 241);
  text('Stewarts Christchurch Garden Centre, BH23 4SA. Please contact Coastal to check opening times and arrange your visit.', M, 250, CW, 9.3);
  text(`${CONTACT.phone} | ${CONTACT.email}`, M, 260, CW, 8.3, C.muted);
  doc.link(M, 256, doc.getTextWidth(CONTACT.phone), 5, { url: CONTACT.phoneLink });
  const emailX = M + doc.getTextWidth(`${CONTACT.phone} | `);
  doc.link(emailX, 256, doc.getTextWidth(CONTACT.email), 5, { url: `mailto:${CONTACT.email}` });
  button(CONTACT.phone, M, 263, 51, CONTACT.phoneLink); button('Email Coastal', M + 57, 263, 54, `mailto:${CONTACT.email}`, false); button('Reopen design', M + 117, 263, 59, resume, false);
  doc.link(M, 250, CW, 5, { url: CONTACT.web });
  doc.setLanguage('en-GB');
  return new Uint8Array(doc.output('arraybuffer'));
}
